(764839, 83705, 21478, '<td valign="top">This looks like the sky is the focus - I would have darkened the ground, and made the sky lighter. Also - perhaps during early evening or morning - longer shadows would have added depth to the shadows etc.</td>', 'This looks like the sky is the focus - I would have darkened the ground, and made the sky lighter. Also - perhaps during early evening or morning - longer shadows would have added depth to the shadows etc.', '2004-06-16 01:09:48.000000', NULL, 1),
(764841, 83892, 21478, '<td valign="top">The focus on the front lipstick is not quite spot on, and makes it difficult to view.</td>', 'The focus on the front lipstick is not quite spot on, and makes it difficult to view.', '2004-06-16 01:10:39.000000', NULL, 1),
(764844, 83962, 21478, '<td valign="top">The subject looks to dark. But I like the image.</td>', 'The subject looks to dark. But I like the image.', '2004-06-16 01:11:17.000000', NULL, 1),
(764847, 83739, 21478, '<td valign="top">Great shot - nice lighting. Would have added drama if the coin was blurred in a spin!</td>', 'Great shot - nice lighting. Would have added drama if the coin was blurred in a spin!', '2004-06-16 01:12:21.000000', NULL, 1),
