(767512, 84030, 18098, '<td valign="top">Very nice.  Great choice for this contest.  Good luck.</td>', 'Very nice.  Great choice for this contest.  Good luck.', '2004-06-17 12:29:00.000000', NULL, 1),
(767516, 83297, 18098, '<td valign="top">I like this picture.  The colors are good and it is a great idea for this callenge.  Lighting seems a little harsh from the side and back.  Good luck.</td>', 'I like this picture.  The colors are good and it is a great idea for this callenge.  Lighting seems a little harsh from the side and back.  Good luck.', '2004-06-17 12:30:58.000000', NULL, 1),
(767519, 83705, 7969, '<td valign="top">I like this shot, you may just want to adjust the horizon, it is a little tilted. Where is this? Hope ya let us know : )</td>', 'I like this shot, you may just want to adjust the horizon, it is a little tilted. Where is this? Hope ya let us know : )', '2004-06-17 12:38:45.000000', NULL, 1),
