INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(767533, 83298, 18098, '<td valign="top">Cool!</td>', 'Cool!', '2004-06-17 12:59:11.000000', NULL, 1),
(767537, 82550, 17357, '<td valign="top">this one kinda creeped me out a bit.... my first thought was, "is this a choice between little girls and ice cream?" then i realized it was little girls choosing ice cream... big difference.</td>', 'this one kinda creeped me out a bit.... my first thought was, "is this a choice between little girls and ice cream?" then i realized it was little girls choosing ice cream... big difference.', '2004-06-17 13:10:29.000000', NULL, 1),
(767565, 83931, 11895, '<td valign="top">hot dog or t-bone?  doesn''t fit the challenge, no choice, I''ll eat them both,  very good pic</td>', 'hot dog or t-bone?  doesn''t fit the challenge, no choice, I''ll eat them both,  very good pic', '2004-06-17 13:52:09.000000', NULL, 1),
(767574, 83298, 21478, '<td valign="top">Seems a little grainy and washed out. Great concept though, with good composition and framing.</td>', 'Seems a little grainy and washed out. Great concept though, with good composition and framing.', '2004-06-17 13:59:38.000000', NULL, 1),
(767576, 83968, 21478, '<td valign="top">This is cool - nice background of the prime time tv pages. But it looks a little like you''ve created a fake shadow (some kind of mask to remove the blye from the paper?) Perhaps making it a little blurred would have helped.</td>', 'This is cool - nice background of the prime time tv pages. But it looks a little like you''ve created a fake shadow (some kind of mask to remove the blye from the paper?) Perhaps making it a little blurred would have helped.', '2004-06-17 14:02:08.000000', NULL, 1),
(767577, 82504, 21478, '<td valign="top">Nice shot with nice angle and good concept. Well placed objects next to each other, almost creating a leading line effect. The lighting is okay - perhaps a bit brighter would have added some more "white" to the milk (but that''s just my take).</td>', 'Nice shot with nice angle and good concept. Well placed objects next to each other, almost creating a leading line effect. The lighting is okay - perhaps a bit brighter would have added some more "white" to the milk (but that''s just my take).', '2004-06-17 14:03:20.000000', NULL, 1),
(767578, 83911, 21478, '<td valign="top">Great shot - looks complex but actually feels simple - the colors work well, and the timer at 1 sec is a cool extra touch! I would have cleaned the scissor blades - just seems like a small distraction. Nice work.</td>', 'Great shot - looks complex but actually feels simple - the colors work well, and the timer at 1 sec is a cool extra touch! I would have cleaned the scissor blades - just seems like a small distraction. Nice work.', '2004-06-17 14:04:21.000000', NULL, 1),
(767579, 83833, 21478, '<td valign="top">You could have cropped this tighter around the light. I don''t think the clutter to the left of the light is necessary to convey the sense of "brake or not". Good concept.</td>', 'You could have cropped this tighter around the light. I don''t think the clutter to the left of the light is necessary to convey the sense of "brake or not". Good concept.', '2004-06-17 14:05:06.000000', NULL, 1),
(767580, 83981, 21478, '<td valign="top">Great product shots - nice work reducing the shadows and working out effective lighting. The red looks more saturated than the blue, but thats just a small issue (or perhaps you *chose* it to be that way :-) )</td>', 'Great product shots - nice work reducing the shadows and working out effective lighting. The red looks more saturated than the blue, but thats just a small issue (or perhaps you *chose* it to be that way :-) )', '2004-06-17 14:06:33.000000', NULL, 1),
(767581, 83569, 21478, '<td valign="top">I thought of a similar concept before I finally entered my shot. Nice work. The picture is quite tall, and I would have gone for a shelf or two less... just to make it easier to view - perhaps a wider shot with a longer depth of field. Nice work.</td>', 'I thought of a similar concept before I finally entered my shot. Nice work. The picture is quite tall, and I would have gone for a shelf or two less... just to make it easier to view - perhaps a wider shot with a longer depth of field. Nice work.', '2004-06-17 14:07:35.000000', NULL, 1),
(767583, 83974, 21478, '<td valign="top">Good concept - but the colors seem flat and dull. Also - the reflection on the plate (near the bottom cauliflower) is a little distracting. Also note that the pizza is cropped slightly off center on the side- perhaps making it more centered on the side would have added some more "structured" lines to the image and created a nicer balance.</td>', 'Good concept - but the colors seem flat and dull. Also - the reflection on the plate (near the bottom cauliflower) is a little distracting. Also note that the pizza is cropped slightly off center on the side- perhaps making it more centered on the side would have added some more "structured" lines to the image and created a nicer balance.', '2004-06-17 14:09:20.000000', NULL, 1),
(767586, 83688, 21478, '<td valign="top">This is nice - but I think a top down shot of the buckets with fish would have conveyed more "choice". The shot subject seems to be the man with the bowl than the fish. Making the fish in the buckets more of the subject would have added more to this. you could crop this in the middle (and keep the bottom), to better convey choice.</td>', 'This is nice - but I think a top down shot of the buckets with fish would have conveyed more "choice". The shot subject seems to be the man with the bowl than the fish. Making the fish in the buckets more of the subject would have added more to this. you could crop this in the middle (and keep the bottom), to better convey choice.', '2004-06-17 14:11:21.000000', NULL, 1),
(767589, 83353, 21478, '<td valign="top">I like the concept (and I don''t know if its intentional), but the sky is missing! This is distracting to me, and loses some of the impact of the phoot. Also, I don''t know who you are - so is your choice the two of them? or are you the guy and like the girl, or the girl and like the guy? Get what I mean? Focus on your subject and you''ll be able to convey more. A tight crop of the face would better indicate who your "choice" is.</td>', 'I like the concept (and I don''t know if its intentional), but the sky is missing! This is distracting to me, and loses some of the impact of the phoot. Also, I don''t know who you are - so is your choice the two of them? or are you the guy and like the girl, or the girl and like the guy? Get what I mean? Focus on your subject and you''ll be able to convey more. A tight crop of the face would better indicate who your "choice" is.', '2004-06-17 14:14:44.000000', NULL, 1),
(767591, 83703, 21478, '<td valign="top">I guess I just don''t get the choice here. To take the pill or not? To take all the pills at once? and what does the Vanity title mean? Sorry for my ignorance. Interesting photo though - with a nice tinge of the blue (Viagra?). Good work with the lighting as well. Is this a negative image?</td>', 'I guess I just don''t get the choice here. To take the pill or not? To take all the pills at once? and what does the Vanity title mean? Sorry for my ignorance. Interesting photo though - with a nice tinge of the blue (Viagra?). Good work with the lighting as well. Is this a negative image?', '2004-06-17 14:16:48.000000', NULL, 1),
(767592, 83002, 21478, '<td valign="top">Just my opinion - I would have cropped this just to be sign. The other stuff just makes it look a little cluttered.</td>', 'Just my opinion - I would have cropped this just to be sign. The other stuff just makes it look a little cluttered.', '2004-06-17 14:17:30.000000', NULL, 1),
(767593, 83893, 21478, '<td valign="top">This could be a better shot with more lighting. Most product shots try to reduce shadows by throwing multiple diffused light around - removing or reducing the shadows significantly (check out the almond bar photo in this contest - not mine). Also - I don''t know how healthy those bananas look - I would have gone for more complete yellow to get the concept across.</td>', 'This could be a better shot with more lighting. Most product shots try to reduce shadows by throwing multiple diffused light around - removing or reducing the shadows significantly (check out the almond bar photo in this contest - not mine). Also - I don''t know how healthy those bananas look - I would have gone for more complete yellow to get the concept across.', '2004-06-17 14:19:08.000000', NULL, 1),
(767594, 83790, 21478, '<td valign="top">The jeans and the dress (with the tassles I assume) really only detract from this image. Just the shoes would have been enough given the title. Also - from the composition - looks like the decision is sneakers (which by the way you can go out and stay in with).</td>', 'The jeans and the dress (with the tassles I assume) really only detract from this image. Just the shoes would have been enough given the title. Also - from the composition - looks like the decision is sneakers (which by the way you can go out and stay in with).', '2004-06-17 14:21:02.000000', NULL, 1),
(767595, 83381, 21478, '<td valign="top">Looks like the choice has been made here. I would have left all three cards turned over. Very patriotic by the way. Good lighting. If you do turn over a card - a red card (perhaps ace of hearts), would have given this more of a leading line across the shot (with red diagnal being perceived as the line). Great concept though.</td>', 'Looks like the choice has been made here. I would have left all three cards turned over. Very patriotic by the way. Good lighting. If you do turn over a card - a red card (perhaps ace of hearts), would have given this more of a leading line across the shot (with red diagnal being perceived as the line). Great concept though.', '2004-06-17 14:22:19.000000', NULL, 1),
(767596, 83328, 21478, '<td valign="top">Great shot. Well cropped and nicely lit.</td>', 'Great shot. Well cropped and nicely lit.', '2004-06-17 14:23:02.000000', NULL, 1),
(767597, 83042, 21478, '<td valign="top">A tighter front on crop of just a bunch of hats with their wavy fronts would have been more impactfull and made for a more balanced, even colored picture. The t-shirts on the right, and the slight angle detract from this image.</td>', 'A tighter front on crop of just a bunch of hats with their wavy fronts would have been more impactfull and made for a more balanced, even colored picture. The t-shirts on the right, and the slight angle detract from this image.', '2004-06-17 14:26:10.000000', NULL, 1),
(767598, 83196, 21478, '<td valign="top">Some of the snow(?) seems blown out, and lacks detail. Perhaps your choice? I don''t get the choice in the image...</td>', 'Some of the snow(?) seems blown out, and lacks detail. Perhaps your choice? I don''t get the choice in the image...', '2004-06-17 14:26:58.000000', NULL, 1),
(767599, 83649, 16965, '<td valign="top">Great IR :)</td>', 'Great IR :)', '2004-06-17 14:27:45.000000', NULL, 1),
