(771568, 83962, 22825, '<td valign="top">Nice shot.  I might have cropped off the bottom to just below the sign post.  7</td>', 'Nice shot.  I might have cropped off the bottom to just below the sign post.  7', '2004-06-21 14:20:35.000000', NULL, 1),
